import { Router } from 'express';
import crypto from 'node:crypto';
import { z } from 'zod';
import { getPool, sql } from '../config/db.js';
import { requireAuth } from '../middleware/auth.js';
import { asyncHandler, AppError } from '../utils/errors.js';
import { audit } from '../services/audit.js';
import { hasPermission, requireCommunityMember, requirePermission } from '../services/permissions.js';
import { getRedis } from '../config/redis.js';
import { env } from '../config/env.js';

export const platformRouter = Router();
platformRouter.use(requireAuth);

const categories=['CDA / Residents Associations','Sports','Parents','Professional','Youth','Charity','Cultural','Educational','Religious','Social'] as const;

// Discovery preferences use coarse town/postcode only. No member GPS coordinates are exposed.
platformRouter.get('/discovery/preferences', asyncHandler(async(req,res)=>{
  const pool=await getPool();
  const r=await pool.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT DiscoveryEnabled,Town,Postcode,PreferredRadiusKm FROM UserDiscoveryPreferences WHERE UserId=@u`);
  res.json(r.recordset[0]??{DiscoveryEnabled:false,Town:null,Postcode:null,PreferredRadiusKm:25});
}));
platformRouter.put('/discovery/preferences', asyncHandler(async(req,res)=>{
  const d=z.object({discoveryEnabled:z.boolean(),town:z.string().max(120).optional().nullable(),postcode:z.string().max(20).optional().nullable(),preferredRadiusKm:z.number().int().min(1).max(100).default(25)}).parse(req.body);
  const pool=await getPool();
  await pool.request().input('u',sql.UniqueIdentifier,req.user!.id).input('e',sql.Bit,d.discoveryEnabled).input('t',sql.NVarChar(120),d.town??null).input('p',sql.NVarChar(20),d.postcode??null).input('r',sql.Int,d.preferredRadiusKm).query(`MERGE UserDiscoveryPreferences t USING(SELECT @u UserId)s ON t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET DiscoveryEnabled=@e,Town=@t,Postcode=@p,PreferredRadiusKm=@r,UpdatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(UserId,DiscoveryEnabled,Town,Postcode,PreferredRadiusKm) VALUES(@u,@e,@t,@p,@r);`);
  res.json({success:true});
}));
platformRouter.get('/discover/communities', asyncHandler(async(req,res)=>{
  const q=String(req.query.q??'').trim(); const category=String(req.query.category??'').trim(); const town=String(req.query.town??'').trim(); const postcode=String(req.query.postcode??'').trim(); const near=String(req.query.near??'false')==='true';
  const pool=await getPool();
  let pref:any=null;
  if(near){const pr=await pool.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT * FROM UserDiscoveryPreferences WHERE UserId=@u AND DiscoveryEnabled=1`);pref=pr.recordset[0];}
  const areaTown=town||pref?.Town||''; const areaPostcode=postcode||pref?.Postcode||'';
  const r=await pool.request().input('u',sql.UniqueIdentifier,req.user!.id).input('q',sql.NVarChar(250),`%${q}%`).input('cat',sql.NVarChar(80),category).input('town',sql.NVarChar(120),areaTown).input('pc',sql.NVarChar(20),areaPostcode).query(`
    SELECT TOP 60 c.Id,c.Name,c.Description,c.LogoUrl,c.BannerUrl,c.CommunityType,c.Category,c.Country,c.City,c.Postcode,c.IsPrivate,c.IsVerified,c.VerifiedAt,
      CASE WHEN cm.Status='ACTIVE' THEN 'MEMBER' WHEN jr.Status='PENDING' THEN 'PENDING' ELSE 'AVAILABLE' END JoinStatus,
      (SELECT COUNT(*) FROM CommunityMembers x WHERE x.CommunityId=c.Id AND x.Status='ACTIVE') MemberCount
    FROM Communities c
    LEFT JOIN CommunityMembers cm ON cm.CommunityId=c.Id AND cm.UserId=@u
    LEFT JOIN CommunityJoinRequests jr ON jr.CommunityId=c.Id AND jr.UserId=@u AND jr.Status='PENDING'
    WHERE (@q='%%' OR c.Name LIKE @q OR c.Description LIKE @q OR c.City LIKE @q OR c.Postcode LIKE @q OR c.Category LIKE @q)
      AND (@cat='' OR c.Category=@cat OR c.CommunityType=@cat)
      AND (@town='' OR c.City LIKE '%'+@town+'%')
      AND (@pc='' OR c.Postcode LIKE @pc+'%')
    ORDER BY c.IsVerified DESC, MemberCount DESC, c.Name`);
  res.json({categories,nearEnabled:!!pref,items:r.recordset});
}));


platformRouter.get('/communities/:communityId/capabilities', asyncHandler(async(req,res)=>{
 const pool=await getPool(); const r=await pool.request().input('u',sql.UniqueIdentifier,req.user!.id).input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT DISTINCT role.Name RoleName,permission.Code PermissionCode,CASE WHEN community.OwnerUserId=@u THEN 1 ELSE 0 END IsOwner FROM Communities community JOIN CommunityMembers member ON member.CommunityId=community.Id AND member.UserId=@u AND member.Status='ACTIVE' LEFT JOIN CommunityMemberRoles memberRole ON memberRole.CommunityMemberId=member.Id LEFT JOIN Roles role ON role.Id=memberRole.RoleId LEFT JOIN RolePermissions rolePermission ON rolePermission.RoleId=role.Id LEFT JOIN Permissions permission ON permission.Id=rolePermission.PermissionId WHERE community.Id=@c`); if(!r.recordset.length)throw new AppError(403,'Not a member'); const owner=r.recordset.some(x=>!!x.IsOwner);const roles=[...new Set(r.recordset.map(x=>x.RoleName).filter(Boolean))] as string[];if(owner&&!roles.includes('Owner'))roles.unshift('Owner');const permissions=new Set<string>(r.recordset.map(x=>x.PermissionCode).filter(Boolean));const manager=owner||roles.some(role=>['Owner','Admin'].includes(role));if(manager)['COMMUNITY_EDIT','MEMBER_INVITE','MEMBER_ROLE_CHANGE','MEMBER_REMOVE','CHAT_CREATE','CHAT_MODERATE','MEETING_CREATE','MEETING_EDIT','ATTENDANCE_MANAGE','POLL_CREATE','POLL_CLOSE','EMERGENCY_SEND','ANNOUNCEMENT_CREATE','DOCUMENT_UPLOAD','DOCUMENT_DELETE','GOVERNANCE_MANAGE','FORMAL_VOTE_MANAGE','FINANCE_MANAGE','DOCUMENT_MANAGE','MODERATION_REVIEW','ANALYTICS_VIEW','DIRECTORY_MANAGE','EVENT_CREATE','OPPORTUNITY_MANAGE','VERIFICATION_SUBMIT'].forEach(permission=>permissions.add(permission));else if(roles.includes('Moderator')){permissions.add('MEMBER_ROLE_CHANGE');permissions.add('MEMBER_REMOVE')}res.json({roles,permissions:[...permissions],isOwner:owner,canManageCommunity:manager});
}));
platformRouter.post('/verification/:requestId/review', asyncHandler(async(req,res)=>{
 const reviewers=env.PLATFORM_ADMIN_EMAILS.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean); if(!reviewers.includes(req.user!.email.toLowerCase()))throw new AppError(403,'Platform verification reviewer access required');
 const d=z.object({decision:z.enum(['APPROVE','REJECT']),reviewNotes:z.string().max(2000).optional()}).parse(req.body); const pool=await getPool(); const vr=await pool.request().input('id',sql.UniqueIdentifier,req.params.requestId).query(`SELECT * FROM CommunityVerificationRequests WHERE Id=@id`); const v=vr.recordset[0]; if(!v)throw new AppError(404,'Verification request not found'); const tx=new sql.Transaction(pool);await tx.begin();try{await new sql.Request(tx).input('id',sql.UniqueIdentifier,req.params.requestId).input('u',sql.UniqueIdentifier,req.user!.id).input('s',sql.NVarChar(30),d.decision==='APPROVE'?'APPROVED':'REJECTED').input('n',sql.NVarChar(2000),d.reviewNotes??null).query(`UPDATE CommunityVerificationRequests SET Status=@s,ReviewNotes=@n,ReviewedBy=@u,ReviewedAt=SYSUTCDATETIME() WHERE Id=@id`);if(d.decision==='APPROVE')await new sql.Request(tx).input('c',sql.UniqueIdentifier,v.CommunityId).query(`UPDATE Communities SET IsVerified=1,VerifiedAt=SYSUTCDATETIME() WHERE Id=@c`);await tx.commit();res.json({success:true,status:d.decision});}catch(e){await tx.rollback();throw e;}
}));

// Verification submission. Public verification is only set after a platform review outside this community-admin endpoint.
platformRouter.post('/communities/:communityId/verification', asyncHandler(async(req,res)=>{
  await requirePermission(req.user!.id,req.params.communityId,'VERIFICATION_SUBMIT');
  const d=z.object({organisationName:z.string().min(2).max(200),registrationNumber:z.string().max(120).optional(),evidenceUrl:z.string().url(),notes:z.string().max(2000).optional()}).parse(req.body);
  const pool=await getPool();
  const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('o',sql.NVarChar(200),d.organisationName).input('rn',sql.NVarChar(120),d.registrationNumber??null).input('e',sql.NVarChar(1000),d.evidenceUrl).input('n',sql.NVarChar(2000),d.notes??null).query(`INSERT INTO CommunityVerificationRequests(CommunityId,SubmittedBy,OrganisationName,RegistrationNumber,EvidenceUrl,Notes) OUTPUT INSERTED.* VALUES(@c,@u,@o,@rn,@e,@n)`);
  await audit(req.params.communityId,req.user!.id,'VERIFICATION_SUBMITTED','CommunityVerificationRequest',r.recordset[0].Id); res.status(201).json(r.recordset[0]);
}));
platformRouter.get('/communities/:communityId/verification', asyncHandler(async(req,res)=>{
  await requireCommunityMember(req.user!.id,req.params.communityId); const pool=await getPool();
  const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT TOP 1 v.*,c.IsVerified,c.VerifiedAt FROM CommunityVerificationRequests v JOIN Communities c ON c.Id=v.CommunityId WHERE v.CommunityId=@c ORDER BY v.CreatedAt DESC`); res.json(r.recordset[0]??null);
}));

// Community issue reporting
platformRouter.get('/communities/:communityId/issues', asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const manager=await hasPermission(req.user!.id,req.params.communityId,'ISSUE_MANAGE');const pool=await getPool();const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('manager',sql.Bit,manager).query(`SELECT i.*,u.FirstName,u.LastName,a.FirstName AssignedFirstName,a.LastName AssignedLastName FROM CommunityIssues i JOIN Users u ON u.Id=i.ReportedBy LEFT JOIN Users a ON a.Id=i.AssignedTo WHERE i.CommunityId=@c AND (@manager=1 OR i.ReportedBy=@u) ORDER BY CASE i.Status WHEN 'SUBMITTED' THEN 0 WHEN 'ASSIGNED' THEN 1 WHEN 'IN_PROGRESS' THEN 2 ELSE 3 END,i.CreatedAt DESC`);res.json(r.recordset);}));
platformRouter.post('/communities/:communityId/issues', asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const d=z.object({category:z.enum(['Inappropriate Content','Harassment or Bullying','Spam or Scams','Fake Profile','Violence or Threats','Hate Speech','Privacy Violation','Broken streetlight','Pothole','Waste problem','Water issue','Security concern','Noise','Damaged facility','Flooding','Other']),title:z.string().min(2).max(250),description:z.string().min(3).max(4000),photoUrl:z.string().url().optional(),approximateLocation:z.string().max(250).optional()}).parse(req.body);const pool=await getPool();const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('cat',sql.NVarChar(80),d.category).input('t',sql.NVarChar(250),d.title).input('d',sql.NVarChar(4000),d.description).input('p',sql.NVarChar(1000),d.photoUrl??null).input('l',sql.NVarChar(250),d.approximateLocation??null).query(`INSERT INTO CommunityIssues(CommunityId,ReportedBy,Category,Title,Description,PhotoUrl,ApproximateLocation) OUTPUT INSERTED.* VALUES(@c,@u,@cat,@t,@d,@p,@l)`);await audit(req.params.communityId,req.user!.id,'ISSUE_REPORTED','CommunityIssue',r.recordset[0].Id);res.status(201).json(r.recordset[0]);}));
platformRouter.patch('/communities/:communityId/issues/:issueId', asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'ISSUE_MANAGE');const d=z.object({status:z.enum(['SUBMITTED','ASSIGNED','IN_PROGRESS','RESOLVED']),assignedTo:z.string().uuid().optional().nullable(),note:z.string().max(2000).optional(),resolutionNote:z.string().max(3000).optional()}).parse(req.body);const pool=await getPool();await pool.request().input('i',sql.UniqueIdentifier,req.params.issueId).input('c',sql.UniqueIdentifier,req.params.communityId).input('s',sql.NVarChar(30),d.status).input('a',sql.UniqueIdentifier,d.assignedTo??null).input('r',sql.NVarChar(3000),d.resolutionNote??null).query(`UPDATE CommunityIssues SET Status=@s,AssignedTo=@a,ResolutionNote=COALESCE(@r,ResolutionNote),ResolvedAt=CASE WHEN @s='RESOLVED' THEN SYSUTCDATETIME() ELSE NULL END,UpdatedAt=SYSUTCDATETIME() WHERE Id=@i AND CommunityId=@c`);if(d.note)await pool.request().input('i',sql.UniqueIdentifier,req.params.issueId).input('u',sql.UniqueIdentifier,req.user!.id).input('s',sql.NVarChar(30),d.status).input('n',sql.NVarChar(2000),d.note).query(`INSERT INTO CommunityIssueUpdates(IssueId,CreatedBy,Status,Note) VALUES(@i,@u,@s,@n)`);await audit(req.params.communityId,req.user!.id,'ISSUE_UPDATED','CommunityIssue',req.params.issueId,{status:d.status});res.json({success:true});}));

// Trusted local service directory
platformRouter.get('/communities/:communityId/services', asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const category=String(req.query.category??'');const pool=await getPool();const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('cat',sql.NVarChar(100),category).query(`SELECT s.*,CAST(ISNULL((SELECT AVG(CAST(Rating AS FLOAT)) FROM ServiceReviews r WHERE r.ProviderId=s.Id),0) AS DECIMAL(3,1)) Rating,(SELECT COUNT(*) FROM ServiceReviews r WHERE r.ProviderId=s.Id) ReviewCount FROM ServiceProviders s WHERE s.CommunityId=@c AND s.Status='ACTIVE' AND (@cat='' OR s.Category=@cat) ORDER BY s.IsVerified DESC,Rating DESC,s.Name`);res.json(r.recordset);}));
platformRouter.post('/communities/:communityId/services', asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const d=z.object({name:z.string().min(2).max(200),category:z.string().min(2).max(100),description:z.string().max(3000).optional(),phone:z.string().max(40).optional(),email:z.string().email().optional(),website:z.string().url().optional(),area:z.string().max(200).optional(),logoUrl:z.string().url().optional()}).parse(req.body);const pool=await getPool();const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('n',sql.NVarChar(200),d.name).input('cat',sql.NVarChar(100),d.category).input('d',sql.NVarChar(3000),d.description??null).input('p',sql.NVarChar(40),d.phone??null).input('e',sql.NVarChar(255),d.email??null).input('w',sql.NVarChar(500),d.website??null).input('a',sql.NVarChar(200),d.area??null).input('l',sql.NVarChar(1000),d.logoUrl??null).query(`INSERT INTO ServiceProviders(CommunityId,CreatedBy,Name,Category,Description,Phone,Email,Website,Area,LogoUrl) OUTPUT INSERTED.* VALUES(@c,@u,@n,@cat,@d,@p,@e,@w,@a,@l)`);res.status(201).json(r.recordset[0]);}));
platformRouter.patch('/communities/:communityId/services/:providerId/verification', asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'DIRECTORY_MANAGE');const {isVerified}=z.object({isVerified:z.boolean()}).parse(req.body);const pool=await getPool();await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('p',sql.UniqueIdentifier,req.params.providerId).input('v',sql.Bit,isVerified).query(`UPDATE ServiceProviders SET IsVerified=@v WHERE Id=@p AND CommunityId=@c`);await audit(req.params.communityId,req.user!.id,isVerified?'SERVICE_VERIFIED':'SERVICE_UNVERIFIED','ServiceProvider',req.params.providerId);res.json({success:true});}));
platformRouter.post('/services/:providerId/reviews', asyncHandler(async(req,res)=>{const d=z.object({rating:z.number().int().min(1).max(5),comment:z.string().max(2000).optional()}).parse(req.body);const pool=await getPool();const s=await pool.request().input('id',sql.UniqueIdentifier,req.params.providerId).query(`SELECT CommunityId FROM ServiceProviders WHERE Id=@id`);if(!s.recordset[0])throw new AppError(404,'Service not found');await requireCommunityMember(req.user!.id,s.recordset[0].CommunityId);await pool.request().input('p',sql.UniqueIdentifier,req.params.providerId).input('u',sql.UniqueIdentifier,req.user!.id).input('r',sql.TinyInt,d.rating).input('c',sql.NVarChar(2000),d.comment??null).query(`MERGE ServiceReviews t USING(SELECT @p ProviderId,@u UserId)s ON t.ProviderId=s.ProviderId AND t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET Rating=@r,Comment=@c,CreatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(ProviderId,UserId,Rating,Comment) VALUES(@p,@u,@r,@c);`);res.json({success:true});}));

platformRouter.get('/communities/:communityId/excos',asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const pool=await getPool();const rows=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT e.Id,e.UserId,e.Position,e.Department,e.AppointedDate,e.TenureEndDate,e.Notes,e.Status,e.CreatedAt,u.FirstName,u.LastName,u.Email,u.Phone,u.ProfileImage,cm.Status MembershipStatus FROM CommunityExecutiveMembers e JOIN Users u ON u.Id=e.UserId JOIN CommunityMembers cm ON cm.CommunityId=e.CommunityId AND cm.UserId=e.UserId AND cm.Status='ACTIVE' WHERE e.CommunityId=@c ORDER BY CASE e.Status WHEN 'ACTIVE' THEN 0 ELSE 1 END,e.Position,u.FirstName,u.LastName`);const canManage=await hasPermission(req.user!.id,req.params.communityId,'MEMBER_ROLE_CHANGE');res.json({items:rows.recordset,canManage});}));
platformRouter.post('/communities/:communityId/excos',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'MEMBER_ROLE_CHANGE');const d=z.object({userId:z.string().uuid(),position:z.string().trim().min(2).max(100),department:z.string().trim().max(150).optional(),appointedDate:z.coerce.date(),tenureEndDate:z.coerce.date().optional(),notes:z.string().trim().max(500).optional()}).parse(req.body);if(d.tenureEndDate&&d.tenureEndDate<d.appointedDate)throw new AppError(400,'Tenure end date must be after the appointment date');const pool=await getPool();const member=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,d.userId).query(`SELECT 1 ok FROM CommunityMembers WHERE CommunityId=@c AND UserId=@u AND Status='ACTIVE'`);if(!member.recordset[0])throw new AppError(400,'Select an active community member');try{const result=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,d.userId).input('p',sql.NVarChar(100),d.position).input('d',sql.NVarChar(150),d.department||null).input('a',sql.Date,d.appointedDate).input('t',sql.Date,d.tenureEndDate||null).input('n',sql.NVarChar(500),d.notes||null).input('by',sql.UniqueIdentifier,req.user!.id).query(`INSERT INTO CommunityExecutiveMembers(CommunityId,UserId,Position,Department,AppointedDate,TenureEndDate,Notes,CreatedBy) OUTPUT INSERTED.* VALUES(@c,@u,@p,@d,@a,@t,@n,@by)`);await audit(req.params.communityId,req.user!.id,'EXCO_APPOINTED','CommunityExecutiveMember',result.recordset[0].Id,{userId:d.userId,position:d.position});res.status(201).json(result.recordset[0])}catch(error:any){if(Number(error?.number)===2601||Number(error?.number)===2627)throw new AppError(409,'This member is already an Exco');throw error}}));
platformRouter.patch('/communities/:communityId/excos/:excoId',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'MEMBER_ROLE_CHANGE');const d=z.object({status:z.enum(['ACTIVE','INACTIVE']),confirmationName:z.string().trim().min(1).max(300)}).parse(req.body);const pool=await getPool();await confirmExcoName(pool,req.params.communityId,req.params.excoId,d.confirmationName);const result=await pool.request().input('id',sql.UniqueIdentifier,req.params.excoId).input('c',sql.UniqueIdentifier,req.params.communityId).input('s',sql.NVarChar(20),d.status).query(`UPDATE CommunityExecutiveMembers SET Status=@s,TenureEndDate=CASE WHEN @s='INACTIVE' THEN COALESCE(TenureEndDate,CAST(SYSUTCDATETIME() AS DATE)) ELSE NULL END,UpdatedAt=SYSUTCDATETIME() WHERE Id=@id AND CommunityId=@c; SELECT @@ROWCOUNT Changed`);if(!result.recordset[0]?.Changed)throw new AppError(404,'Exco appointment not found');await audit(req.params.communityId,req.user!.id,'EXCO_STATUS_CHANGED','CommunityExecutiveMember',req.params.excoId,{status:d.status});res.json({success:true})}));
platformRouter.delete('/communities/:communityId/excos/:excoId',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'MEMBER_ROLE_CHANGE');const d=z.object({confirmationName:z.string().trim().min(1).max(300)}).parse(req.body??{});const pool=await getPool();await confirmExcoName(pool,req.params.communityId,req.params.excoId,d.confirmationName);const result=await pool.request().input('id',sql.UniqueIdentifier,req.params.excoId).input('c',sql.UniqueIdentifier,req.params.communityId).query(`DELETE FROM CommunityExecutiveMembers WHERE Id=@id AND CommunityId=@c; SELECT @@ROWCOUNT Changed`);if(!result.recordset[0]?.Changed)throw new AppError(404,'Exco appointment not found');await audit(req.params.communityId,req.user!.id,'EXCO_REMOVED','CommunityExecutiveMember',req.params.excoId);res.json({success:true})}));

async function confirmExcoName(pool:sql.ConnectionPool,communityId:string,excoId:string,confirmationName:string){const result=await pool.request().input('c',sql.UniqueIdentifier,communityId).input('id',sql.UniqueIdentifier,excoId).query(`SELECT TOP 1 u.FirstName,u.LastName FROM CommunityExecutiveMembers e JOIN Users u ON u.Id=e.UserId WHERE e.Id=@id AND e.CommunityId=@c`);const member=result.recordset[0];if(!member)throw new AppError(404,'Exco appointment not found');const expected=`${member.FirstName||''} ${member.LastName||''}`.trim().toLocaleLowerCase();if(confirmationName.trim().toLocaleLowerCase()!==expected)throw new AppError(400,'The confirmation name does not match this member');}

// Marketplace
platformRouter.get('/communities/:communityId/marketplace', asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const type=String(req.query.type??'');const pool=await getPool();const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('t',sql.NVarChar(30),type).query(`SELECT m.*,u.FirstName,u.LastName,CASE WHEN sm.UserId IS NULL THEN 0 ELSE 1 END IsSaved,CASE WHEN EXISTS(SELECT 1 FROM CommunityMembers cm JOIN CommunityMemberRoles cmr ON cmr.CommunityMemberId=cm.Id JOIN Roles r ON r.Id=cmr.RoleId WHERE cm.UserId=m.SellerUserId AND cm.CommunityId=m.CommunityId AND r.Name IN('Owner','Admin')) THEN 1 ELSE 0 END SellerVerified FROM MarketplaceListings m JOIN Users u ON u.Id=m.SellerUserId LEFT JOIN SavedMarketplaceListings sm ON sm.ListingId=m.Id AND sm.UserId=@u WHERE m.CommunityId=@c AND m.Status='ACTIVE' AND m.ModerationStatus='APPROVED' AND (@t='' OR m.ListingType=@t) ORDER BY m.CreatedAt DESC`);res.json(r.recordset);}));
platformRouter.post('/communities/:communityId/marketplace', asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const d=z.object({listingType:z.enum(['FOR_SALE','FREE','WANTED','SERVICES','RENTALS','JOBS']),title:z.string().min(2).max(220),description:z.string().min(3).max(4000),price:z.number().min(0).optional(),currency:z.string().max(10).default('NGN'),area:z.string().min(2).max(200),imageUrl:z.string().url().optional(),imageUrls:z.array(z.string().url()).max(6).default([]),itemCondition:z.enum(['NEW','LIKE_NEW','GOOD','FAIR','NOT_APPLICABLE']).default('NOT_APPLICABLE'),deliveryOption:z.enum(['MEETUP','DELIVERY']).default('MEETUP'),contactPreference:z.enum(['IN_APP','PHONE','WHATSAPP']).default('IN_APP'),isNegotiable:z.boolean().default(false)}).parse(req.body);const images=d.imageUrls.length?d.imageUrls:d.imageUrl?[d.imageUrl]:[];const pool=await getPool();const tx=new sql.Transaction(pool);await tx.begin();try{const r=await new sql.Request(tx).input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('lt',sql.NVarChar(30),d.listingType).input('t',sql.NVarChar(220),d.title).input('d',sql.NVarChar(4000),d.description).input('p',sql.Decimal(18,2),d.price??null).input('cur',sql.NVarChar(10),d.currency).input('a',sql.NVarChar(200),d.area).input('img',sql.NVarChar(1000),images[0]??null).input('cond',sql.NVarChar(30),d.itemCondition).input('delivery',sql.NVarChar(30),d.deliveryOption).input('contact',sql.NVarChar(30),d.contactPreference).input('neg',sql.Bit,d.isNegotiable).query(`INSERT INTO MarketplaceListings(CommunityId,SellerUserId,ListingType,Title,Description,Price,Currency,Area,ImageUrl,ItemCondition,DeliveryOption,ContactPreference,IsNegotiable) OUTPUT INSERTED.* VALUES(@c,@u,@lt,@t,@d,@p,@cur,@a,@img,@cond,@delivery,@contact,@neg)`);for(let position=0;position<images.length;position++)await new sql.Request(tx).input('l',sql.UniqueIdentifier,r.recordset[0].Id).input('url',sql.NVarChar(1000),images[position]).input('position',sql.Int,position).query(`INSERT INTO MarketplaceListingImages(ListingId,ImageUrl,Position) VALUES(@l,@url,@position)`);await tx.commit();res.status(201).json({...r.recordset[0],ImageUrls:images})}catch(error){await tx.rollback();throw error}}));
platformRouter.post('/marketplace/:listingId/save', asyncHandler(async(req,res)=>{const pool=await getPool();const listing=await pool.request().input('id',sql.UniqueIdentifier,req.params.listingId).query(`SELECT CommunityId FROM MarketplaceListings WHERE Id=@id AND Status='ACTIVE'`);if(!listing.recordset[0])throw new AppError(404,'Listing not found');await requireCommunityMember(req.user!.id,listing.recordset[0].CommunityId);await pool.request().input('l',sql.UniqueIdentifier,req.params.listingId).input('u',sql.UniqueIdentifier,req.user!.id).query(`IF EXISTS(SELECT 1 FROM SavedMarketplaceListings WHERE ListingId=@l AND UserId=@u) DELETE FROM SavedMarketplaceListings WHERE ListingId=@l AND UserId=@u ELSE INSERT INTO SavedMarketplaceListings(ListingId,UserId) VALUES(@l,@u)`);res.json({success:true});}));
platformRouter.post('/marketplace/:listingId/report', asyncHandler(async(req,res)=>{const d=z.object({reason:z.string().min(2).max(120),details:z.string().max(1000).optional()}).parse(req.body);const pool=await getPool();const x=await pool.request().input('id',sql.UniqueIdentifier,req.params.listingId).query(`SELECT CommunityId FROM MarketplaceListings WHERE Id=@id`);if(!x.recordset[0])throw new AppError(404,'Listing not found');await requireCommunityMember(req.user!.id,x.recordset[0].CommunityId);await pool.request().input('l',sql.UniqueIdentifier,req.params.listingId).input('u',sql.UniqueIdentifier,req.user!.id).input('r',sql.NVarChar(120),d.reason).input('d',sql.NVarChar(1000),d.details??null).query(`INSERT INTO MarketplaceReports(ListingId,ReportedBy,Reason,Details) VALUES(@l,@u,@r,@d)`);res.status(201).json({success:true});}));
platformRouter.delete('/communities/:communityId/marketplace/:listingId', asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'MARKETPLACE_MODERATE');const pool=await getPool();await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('id',sql.UniqueIdentifier,req.params.listingId).query(`UPDATE MarketplaceListings SET Status='REMOVED',UpdatedAt=SYSUTCDATETIME() WHERE Id=@id AND CommunityId=@c`);await audit(req.params.communityId,req.user!.id,'MARKETPLACE_REMOVED','MarketplaceListing',req.params.listingId);res.status(204).end();}));

// Jobs and opportunities
platformRouter.get('/communities/:communityId/opportunities', asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const type=String(req.query.type??'');const pool=await getPool();const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('t',sql.NVarChar(40),type).query(`SELECT o.*,CASE WHEN so.UserId IS NULL THEN 0 ELSE 1 END IsSaved FROM CommunityOpportunities o LEFT JOIN SavedOpportunities so ON so.OpportunityId=o.Id AND so.UserId=@u WHERE o.CommunityId=@c AND o.Status='OPEN' AND (@t='' OR o.OpportunityType=@t) ORDER BY CASE WHEN o.Deadline IS NULL THEN 1 ELSE 0 END,o.Deadline,o.CreatedAt DESC`);res.json(r.recordset);}));
platformRouter.post('/communities/:communityId/opportunities', asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'OPPORTUNITY_MANAGE');const d=z.object({opportunityType:z.enum(['JOB','VOLUNTEERING','TRAINING','SCHOLARSHIP','INTERNSHIP','COMMUNITY']),title:z.string().min(2).max(250),description:z.string().min(3).max(5000),organisation:z.string().max(200).optional(),location:z.string().max(200).optional(),applyUrl:z.string().url().optional(),deadline:z.coerce.date().optional()}).parse(req.body);const pool=await getPool();const tx=new sql.Transaction(pool);await tx.begin();try{const r=await new sql.Request(tx).input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('ot',sql.NVarChar(40),d.opportunityType).input('t',sql.NVarChar(250),d.title).input('d',sql.NVarChar(5000),d.description).input('o',sql.NVarChar(200),d.organisation??null).input('l',sql.NVarChar(200),d.location??null).input('a',sql.NVarChar(1000),d.applyUrl??null).input('dl',sql.DateTime2,d.deadline??null).query(`INSERT INTO CommunityOpportunities(CommunityId,CreatedBy,OpportunityType,Title,Description,Organisation,Location,ApplyUrl,Deadline) OUTPUT INSERTED.* VALUES(@c,@u,@ot,@t,@d,@o,@l,@a,@dl)`);const body=[`${d.opportunityType.replace('_',' ')}: ${d.title}`,d.description,d.organisation?`Organisation: ${d.organisation}`:'',d.location?`Location: ${d.location}`:'',d.deadline?`Deadline: ${d.deadline.toLocaleDateString()}`:''].filter(Boolean).join('\n\n');const post=await new sql.Request(tx).input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('b',sql.NVarChar(sql.MAX),body).input('url',sql.NVarChar(1500),d.applyUrl??null).query(`INSERT INTO CommunityPosts(CommunityId,CreatedBy,Body,PostType,MediaUrl,MediaType) OUTPUT INSERTED.Id VALUES(@c,@u,@b,'OPPORTUNITY',@url,CASE WHEN @url IS NULL THEN NULL ELSE 'text/uri-list' END)`);await tx.commit();await audit(req.params.communityId,req.user!.id,'OPPORTUNITY_PUBLISHED','CommunityOpportunity',r.recordset[0].Id,{feedPostId:post.recordset[0].Id});res.status(201).json({...r.recordset[0],FeedPostId:post.recordset[0].Id})}catch(error){await tx.rollback();throw error}}));
platformRouter.post('/opportunities/:opportunityId/save', asyncHandler(async(req,res)=>{const pool=await getPool();const o=await pool.request().input('id',sql.UniqueIdentifier,req.params.opportunityId).query(`SELECT CommunityId FROM CommunityOpportunities WHERE Id=@id`);if(!o.recordset[0])throw new AppError(404,'Opportunity not found');await requireCommunityMember(req.user!.id,o.recordset[0].CommunityId);await pool.request().input('o',sql.UniqueIdentifier,req.params.opportunityId).input('u',sql.UniqueIdentifier,req.user!.id).query(`IF EXISTS(SELECT 1 FROM SavedOpportunities WHERE OpportunityId=@o AND UserId=@u) DELETE FROM SavedOpportunities WHERE OpportunityId=@o AND UserId=@u ELSE INSERT INTO SavedOpportunities(OpportunityId,UserId) VALUES(@o,@u)`);res.json({success:true});}));

// Events
platformRouter.get('/communities/:communityId/events', asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const pool=await getPool();const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT e.*,ea.Status MyStatus,ea.CheckedInAt,(SELECT COUNT(*) FROM EventAttendees x WHERE x.EventId=e.Id AND x.Status='GOING') GoingCount,(SELECT COUNT(*) FROM EventAttendees x WHERE x.EventId=e.Id AND x.Status='WAITLIST') WaitlistCount,(SELECT COUNT(*) FROM EventPhotos p WHERE p.EventId=e.Id) PhotoCount,(SELECT TOP 1 p.PhotoUrl FROM EventPhotos p WHERE p.EventId=e.Id ORDER BY p.CreatedAt DESC) LastPhotoUrl FROM CommunityEvents e LEFT JOIN EventAttendees ea ON ea.EventId=e.Id AND ea.UserId=@u WHERE e.CommunityId=@c ORDER BY e.StartDateTime`);res.json(r.recordset);}));
platformRouter.post('/communities/:communityId/events', asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'EVENT_CREATE');const d=z.object({title:z.string().min(2).max(250),description:z.string().max(5000).optional(),eventType:z.string().max(80).optional(),location:z.string().max(500).optional(),startDateTime:z.coerce.date(),endDateTime:z.coerce.date(),capacity:z.number().int().positive().optional(),allowWaitlist:z.boolean().default(true),reminderMinutes:z.number().int().min(0).optional(),coverImageUrl:z.string().url().optional()}).parse(req.body);const pool=await getPool();const tx=new sql.Transaction(pool);await tx.begin();try{const cv=await new sql.Request(tx).input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('n',sql.NVarChar(200),d.title).query(`INSERT INTO Conversations(CommunityId,Name,Type,CreatedBy) OUTPUT INSERTED.Id VALUES(@c,@n,'EVENT',@u)`);const r=await new sql.Request(tx).input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('t',sql.NVarChar(250),d.title).input('d',sql.NVarChar(5000),d.description??null).input('et',sql.NVarChar(80),d.eventType??null).input('l',sql.NVarChar(500),d.location??null).input('s',sql.DateTime2,d.startDateTime).input('e',sql.DateTime2,d.endDateTime).input('cap',sql.Int,d.capacity??null).input('w',sql.Bit,d.allowWaitlist).input('rm',sql.Int,d.reminderMinutes??null).input('img',sql.NVarChar(1000),d.coverImageUrl??null).input('cv',sql.UniqueIdentifier,cv.recordset[0].Id).query(`INSERT INTO CommunityEvents(CommunityId,CreatedBy,Title,Description,EventType,Location,StartDateTime,EndDateTime,Capacity,AllowWaitlist,ReminderMinutes,CoverImageUrl,ConversationId) OUTPUT INSERTED.* VALUES(@c,@u,@t,@d,@et,@l,@s,@e,@cap,@w,@rm,@img,@cv)`);await tx.commit();res.status(201).json(r.recordset[0]);}catch(e){await tx.rollback();throw e;}}));
platformRouter.post('/events/:eventId/rsvp', asyncHandler(async(req,res)=>{const d=z.object({status:z.enum(['GOING','NOT_GOING'])}).parse(req.body);const pool=await getPool();const er=await pool.request().input('e',sql.UniqueIdentifier,req.params.eventId).query(`SELECT * FROM CommunityEvents WHERE Id=@e`);const event=er.recordset[0];if(!event)throw new AppError(404,'Event not found');await requireCommunityMember(req.user!.id,event.CommunityId);let status:'GOING'|'NOT_GOING'|'WAITLIST'=d.status;if(status==='GOING'&&event.Capacity){const cr=await pool.request().input('e',sql.UniqueIdentifier,req.params.eventId).query(`SELECT COUNT(*) n FROM EventAttendees WHERE EventId=@e AND Status='GOING'`);if(cr.recordset[0].n>=event.Capacity)status=event.AllowWaitlist?'WAITLIST':'NOT_GOING';}await pool.request().input('e',sql.UniqueIdentifier,req.params.eventId).input('u',sql.UniqueIdentifier,req.user!.id).input('s',sql.NVarChar(30),status).query(`MERGE EventAttendees t USING(SELECT @e EventId,@u UserId)s ON t.EventId=s.EventId AND t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET Status=@s WHEN NOT MATCHED THEN INSERT(EventId,UserId,Status) VALUES(@e,@u,@s); INSERT INTO ConversationMembers(ConversationId,UserId) SELECT ConversationId,@u FROM CommunityEvents WHERE Id=@e AND ConversationId IS NOT NULL AND @s IN ('GOING','WAITLIST') AND NOT EXISTS(SELECT 1 FROM ConversationMembers cm WHERE cm.ConversationId=CommunityEvents.ConversationId AND cm.UserId=@u);`);res.json({success:true,status});}));
platformRouter.post('/events/:eventId/photos', asyncHandler(async(req,res)=>{const {photoUrl}=z.object({photoUrl:z.string().url()}).parse(req.body);const pool=await getPool();const e=await pool.request().input('e',sql.UniqueIdentifier,req.params.eventId).query(`SELECT CommunityId FROM CommunityEvents WHERE Id=@e`);if(!e.recordset[0])throw new AppError(404,'Event not found');await requireCommunityMember(req.user!.id,e.recordset[0].CommunityId);await pool.request().input('e',sql.UniqueIdentifier,req.params.eventId).input('u',sql.UniqueIdentifier,req.user!.id).input('p',sql.NVarChar(1000),photoUrl).query(`INSERT INTO EventPhotos(EventId,UploadedBy,PhotoUrl) VALUES(@e,@u,@p)`);res.status(201).json({success:true});}));

// Meeting attendance
platformRouter.get('/communities/:communityId/attendance',asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const manager=await hasPermission(req.user!.id,req.params.communityId,'ATTENDANCE_MANAGE');const pool=await getPool();await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).query(`UPDATE s SET IsActive=0,UpdatedAt=SYSUTCDATETIME() FROM MeetingAttendanceSessions s JOIN Meetings m ON m.Id=s.MeetingId WHERE m.CommunityId=@c AND m.EndDateTime<=SYSUTCDATETIME() AND s.IsActive=1`);const r=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT m.Id,m.Title,m.Location,m.StartDateTime,m.EndDateTime,s.IsActive,s.CodeExpiresAt,(SELECT COUNT(*) FROM CommunityMembers cm WHERE cm.CommunityId=m.CommunityId AND cm.Status='ACTIVE') MemberCount,(SELECT COUNT(*) FROM MeetingAttendance a WHERE a.MeetingId=m.Id AND a.Status IN('PRESENT','LATE')) PresentCount,(SELECT COUNT(*) FROM MeetingAttendance a WHERE a.MeetingId=m.Id AND a.Status='LATE') LateCount,(SELECT COUNT(*) FROM MeetingAttendance a WHERE a.MeetingId=m.Id AND a.UserId=@u) MyAttendance FROM Meetings m LEFT JOIN MeetingAttendanceSessions s ON s.MeetingId=m.Id WHERE m.CommunityId=@c ORDER BY m.StartDateTime DESC`);res.json({canManage:manager,meetings:r.recordset});}));
platformRouter.get('/meetings/:meetingId/attendance',asyncHandler(async(req,res)=>{const pool=await getPool();await pool.request().input('m',sql.UniqueIdentifier,req.params.meetingId).query(`UPDATE s SET IsActive=0,UpdatedAt=SYSUTCDATETIME() FROM MeetingAttendanceSessions s JOIN Meetings mt ON mt.Id=s.MeetingId WHERE s.MeetingId=@m AND mt.EndDateTime<=SYSUTCDATETIME() AND s.IsActive=1`);const mr=await pool.request().input('m',sql.UniqueIdentifier,req.params.meetingId).query(`SELECT m.*,c.Name CommunityName,s.AttendanceCode,s.CodeExpiresAt,s.IsActive FROM Meetings m JOIN Communities c ON c.Id=m.CommunityId LEFT JOIN MeetingAttendanceSessions s ON s.MeetingId=m.Id WHERE m.Id=@m`);const meeting=mr.recordset[0];if(!meeting)throw new AppError(404,'Meeting not found');await requireCommunityMember(req.user!.id,meeting.CommunityId);const manager=await hasPermission(req.user!.id,meeting.CommunityId,'ATTENDANCE_MANAGE');const ar=await pool.request().input('m',sql.UniqueIdentifier,req.params.meetingId).input('manager',sql.Bit,manager).query(`SELECT cm.UserId,cm.Id MembershipId,u.FirstName,u.LastName,CASE WHEN @manager=1 THEN u.Email END Email,CASE WHEN @manager=1 THEN u.Phone END Phone,u.ProfileImage,mc.CardNumber,a.Status,a.CheckInMethod,a.CheckedInAt FROM CommunityMembers cm JOIN Meetings m ON m.CommunityId=cm.CommunityId JOIN Users u ON u.Id=cm.UserId LEFT JOIN MembershipCards mc ON mc.MembershipId=cm.Id AND mc.IsActive=1 LEFT JOIN MeetingAttendance a ON a.MeetingId=m.Id AND a.UserId=cm.UserId WHERE m.Id=@m AND cm.Status='ACTIVE' ORDER BY CASE WHEN a.CheckedInAt IS NULL THEN 1 ELSE 0 END,a.CheckedInAt DESC,u.FirstName,u.LastName`);const safeMeeting=manager?meeting:{...meeting,AttendanceCode:null,CodeExpiresAt:null};res.json({meeting:safeMeeting,canManage:manager,participants:ar.recordset});}));
platformRouter.post('/meetings/:meetingId/attendance/code',asyncHandler(async(req,res)=>{const pool=await getPool();const mr=await pool.request().input('m',sql.UniqueIdentifier,req.params.meetingId).query('SELECT CommunityId,EndDateTime FROM Meetings WHERE Id=@m');const meeting=mr.recordset[0];if(!meeting)throw new AppError(404,'Meeting not found');await requirePermission(req.user!.id,meeting.CommunityId,'ATTENDANCE_MANAGE');const endAt=new Date(meeting.EndDateTime).getTime();if(endAt<=Date.now())throw new AppError(409,'Attendance is closed because the meeting has ended');const code=String(crypto.randomInt(0,1000000)).padStart(6,'0');const expires=new Date(Math.min(endAt,Date.now()+15*60000));await pool.request().input('m',sql.UniqueIdentifier,req.params.meetingId).input('code',sql.Char(6),code).input('expires',sql.DateTime2,expires).input('u',sql.UniqueIdentifier,req.user!.id).query(`MERGE MeetingAttendanceSessions t USING(SELECT @m MeetingId)s ON t.MeetingId=s.MeetingId WHEN MATCHED THEN UPDATE SET AttendanceCode=@code,CodeExpiresAt=@expires,IsActive=1,UpdatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(MeetingId,AttendanceCode,CodeExpiresAt,CreatedBy) VALUES(@m,@code,@expires,@u);`);res.json({attendanceCode:code,codeExpiresAt:expires,isActive:true});}));
platformRouter.post('/communities/:communityId/attendance/mark',asyncHandler(async(req,res)=>{await requireCommunityMember(req.user!.id,req.params.communityId);const {code}=z.object({code:z.string().regex(/^\d{6}$/)}).parse(req.body);const pool=await getPool();const sr=await pool.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('code',sql.Char(6),code).query(`SELECT TOP 1 s.MeetingId,m.StartDateTime,m.EndDateTime FROM MeetingAttendanceSessions s JOIN Meetings m ON m.Id=s.MeetingId WHERE m.CommunityId=@c AND s.AttendanceCode=@code AND s.IsActive=1 AND s.CodeExpiresAt>=SYSUTCDATETIME() AND m.EndDateTime>SYSUTCDATETIME() ORDER BY m.StartDateTime DESC`);const session=sr.recordset[0];if(!session)throw new AppError(400,'The attendance code is invalid, expired or the meeting has ended');const late=Date.now()>new Date(session.StartDateTime).getTime()+15*60000;await pool.request().input('m',sql.UniqueIdentifier,session.MeetingId).input('u',sql.UniqueIdentifier,req.user!.id).input('status',sql.NVarChar(20),late?'LATE':'PRESENT').query(`MERGE MeetingAttendance t USING(SELECT @m MeetingId,@u UserId)s ON t.MeetingId=s.MeetingId AND t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET Status=@status,CheckInMethod='CODE',CheckedInAt=SYSUTCDATETIME(),MarkedBy=@u WHEN NOT MATCHED THEN INSERT(MeetingId,UserId,Status,CheckInMethod,MarkedBy) VALUES(@m,@u,@status,'CODE',@u);`);res.json({success:true,meetingId:session.MeetingId,status:late?'LATE':'PRESENT'});}));
platformRouter.post('/meetings/:meetingId/attendance/members/:userId',asyncHandler(async(req,res)=>{const {status}=z.object({status:z.enum(['PRESENT','LATE','ABSENT'])}).parse(req.body);const pool=await getPool();const mr=await pool.request().input('m',sql.UniqueIdentifier,req.params.meetingId).query('SELECT CommunityId,EndDateTime FROM Meetings WHERE Id=@m');if(!mr.recordset[0])throw new AppError(404,'Meeting not found');await requirePermission(req.user!.id,mr.recordset[0].CommunityId,'ATTENDANCE_MANAGE');if(new Date(mr.recordset[0].EndDateTime).getTime()<=Date.now())throw new AppError(409,'Attendance is closed because the meeting has ended');await pool.request().input('m',sql.UniqueIdentifier,req.params.meetingId).input('u',sql.UniqueIdentifier,req.params.userId).input('status',sql.NVarChar(20),status).input('by',sql.UniqueIdentifier,req.user!.id).query(`IF NOT EXISTS(SELECT 1 FROM CommunityMembers cm JOIN Meetings mt ON mt.CommunityId=cm.CommunityId WHERE mt.Id=@m AND cm.UserId=@u AND cm.Status='ACTIVE') THROW 50001,'Member not found',1; MERGE MeetingAttendance t USING(SELECT @m MeetingId,@u UserId)s ON t.MeetingId=s.MeetingId AND t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET Status=@status,CheckInMethod='MANUAL',CheckedInAt=SYSUTCDATETIME(),MarkedBy=@by WHEN NOT MATCHED THEN INSERT(MeetingId,UserId,Status,CheckInMethod,MarkedBy) VALUES(@m,@u,@status,'MANUAL',@by);`);res.json({success:true});}));
platformRouter.post('/meetings/:meetingId/attendance/end',asyncHandler(async(req,res)=>{const pool=await getPool();const mr=await pool.request().input('m',sql.UniqueIdentifier,req.params.meetingId).query('SELECT CommunityId FROM Meetings WHERE Id=@m');if(!mr.recordset[0])throw new AppError(404,'Meeting not found');await requirePermission(req.user!.id,mr.recordset[0].CommunityId,'ATTENDANCE_MANAGE');await pool.request().input('m',sql.UniqueIdentifier,req.params.meetingId).query(`UPDATE MeetingAttendanceSessions SET IsActive=0,UpdatedAt=SYSUTCDATETIME() WHERE MeetingId=@m`);res.json({success:true});}));

// Digital membership card and QR check-in
platformRouter.get('/communities/:communityId/membership-card', asyncHandler(async(req,res)=>{const membershipId=await requireCommunityMember(req.user!.id,req.params.communityId),pool=await getPool();await pool.request().input('m',sql.UniqueIdentifier,membershipId).query(`UPDATE MembershipCards SET IsActive=0 WHERE MembershipId=@m AND IsActive=1 AND ExpiresAt IS NOT NULL AND ExpiresAt<=SYSUTCDATETIME()`);let card=(await pool.request().input('m',sql.UniqueIdentifier,membershipId).query(`SELECT * FROM MembershipCards WHERE MembershipId=@m AND IsActive=1 AND (ExpiresAt IS NULL OR ExpiresAt>SYSUTCDATETIME())`)).recordset[0];if(!card){const cardNumber='CDA-'+crypto.randomBytes(5).toString('hex').toUpperCase(),token=crypto.randomBytes(24).toString('base64url');card=(await pool.request().input('m',sql.UniqueIdentifier,membershipId).input('n',sql.NVarChar(50),cardNumber).input('q',sql.NVarChar(120),token).query(`INSERT INTO MembershipCards(MembershipId,CardNumber,QrToken) OUTPUT INSERTED.* VALUES(@m,@n,@q)`)).recordset[0]}const data=(await pool.request().input('m',sql.UniqueIdentifier,membershipId).input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT cm.UserId,cm.JoinedAt,cm.Status MembershipStatus,u.FirstName,u.LastName,u.Email,u.Phone,u.ProfileImage,u.Country,u.State,u.LGA,c.Name CommunityName,c.LogoUrl CommunityLogo,c.IsVerified CommunityVerified,(SELECT STRING_AGG(roleName.Name,', ') FROM(SELECT DISTINCT r.Name FROM CommunityMemberRoles cmr JOIN Roles r ON r.Id=cmr.RoleId WHERE cmr.CommunityMemberId=cm.Id) roleName) Roles,(SELECT TOP 1 ex.Position FROM CommunityExecutiveMembers ex WHERE ex.CommunityId=cm.CommunityId AND ex.UserId=cm.UserId AND ex.Status='ACTIVE' ORDER BY ex.AppointedDate DESC,ex.Id) ExcoPosition,(SELECT COUNT(*) FROM CommunityMembers x WHERE x.CommunityId=cm.CommunityId AND x.Status='ACTIVE') CommunityMemberCount,(SELECT COUNT(*) FROM MeetingAttendance a JOIN Meetings mt ON mt.Id=a.MeetingId WHERE mt.CommunityId=cm.CommunityId AND a.UserId=@u AND a.Status IN('PRESENT','LATE')) CheckInCount,(SELECT COUNT(DISTINCT pv.PollId) FROM PollVotes pv JOIN Polls p ON p.Id=pv.PollId WHERE p.CommunityId=cm.CommunityId AND pv.UserId=@u) VoteCount,(SELECT COUNT(*) FROM CommunityPosts cp WHERE cp.CommunityId=cm.CommunityId AND cp.CreatedBy=@u AND cp.IsDeleted=0) PostCount,(SELECT COUNT(*) FROM PostReactions pr JOIN CommunityPosts cp ON cp.Id=pr.PostId WHERE cp.CommunityId=cm.CommunityId AND cp.CreatedBy=@u AND cp.IsDeleted=0) ReactionCount,(SELECT MAX(a.CheckedInAt) FROM MeetingAttendance a JOIN Meetings mt ON mt.Id=a.MeetingId WHERE mt.CommunityId=cm.CommunityId AND a.UserId=@u) LastCheckIn FROM CommunityMembers cm JOIN Users u ON u.Id=cm.UserId JOIN Communities c ON c.Id=cm.CommunityId WHERE cm.Id=@m AND cm.Status='ACTIVE'`)).recordset[0];if(!data)throw new AppError(404,'Active membership card not found');res.json({...card,...data,QrPayload:`CDACONNECT:${card.QrToken}`})}));
platformRouter.post('/communities/:communityId/membership-card/rotate',asyncHandler(async(req,res)=>{const membershipId=await requireCommunityMember(req.user!.id,req.params.communityId),pool=await getPool(),token=crypto.randomBytes(24).toString('base64url');await pool.request().input('m',sql.UniqueIdentifier,membershipId).input('q',sql.NVarChar(120),token).query(`UPDATE MembershipCards SET QrToken=@q WHERE MembershipId=@m AND IsActive=1 AND (ExpiresAt IS NULL OR ExpiresAt>SYSUTCDATETIME())`);await audit(req.params.communityId,req.user!.id,'MEMBERSHIP_CARD_TOKEN_ROTATED','MembershipCard',membershipId);res.json({success:true})}));
platformRouter.post('/communities/:communityId/check-in',asyncHandler(async(req,res)=>{const d=z.object({qrPayload:z.string().min(10),eventId:z.string().uuid().optional(),meetingId:z.string().uuid().optional()}).refine(value=>!(value.eventId&&value.meetingId),{message:'Choose either an event or meeting'}).parse(req.body),redis=getRedis(),rateKey=`membership-scan:${req.user!.id}:${Math.floor(Date.now()/60000)}`,scans=await redis.incr(rateKey);if(scans===1)await redis.expire(rateKey,60);if(scans>30)throw new AppError(429,'Scan rate limit reached');if(d.meetingId)await requirePermission(req.user!.id,req.params.communityId,'ATTENDANCE_MANAGE');else if(d.eventId)await requirePermission(req.user!.id,req.params.communityId,'EVENT_MANAGE');else await requirePermission(req.user!.id,req.params.communityId,'MEMBERSHIP_SCAN');const token=d.qrPayload.replace(/^CDACONNECT:/,''),pool=await getPool(),tx=new sql.Transaction(pool);await tx.begin(sql.ISOLATION_LEVEL.SERIALIZABLE);try{const card=(await new sql.Request(tx).input('q',sql.NVarChar(120),token).input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT mc.Id CardId,cm.UserId,u.FirstName,u.LastName FROM MembershipCards mc WITH(UPDLOCK,HOLDLOCK) JOIN CommunityMembers cm ON cm.Id=mc.MembershipId JOIN Users u ON u.Id=cm.UserId WHERE mc.QrToken=@q AND mc.IsActive=1 AND (mc.ExpiresAt IS NULL OR mc.ExpiresAt>SYSUTCDATETIME()) AND cm.CommunityId=@c AND cm.Status='ACTIVE' AND u.AccountStatus='ACTIVE'`)).recordset[0];if(!card)throw new AppError(404,'Valid membership card not found');let alreadyCheckedIn=false;if(d.eventId){const event=(await new sql.Request(tx).input('e',sql.UniqueIdentifier,d.eventId).input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT Id FROM CommunityEvents WITH(UPDLOCK,HOLDLOCK) WHERE Id=@e AND CommunityId=@c AND EndDateTime>SYSUTCDATETIME()`)).recordset[0];if(!event)throw new AppError(404,'Event not found');const prior=(await new sql.Request(tx).input('e',sql.UniqueIdentifier,d.eventId).input('u',sql.UniqueIdentifier,card.UserId).query(`SELECT CheckedInAt FROM EventAttendees WITH(UPDLOCK,HOLDLOCK) WHERE EventId=@e AND UserId=@u`)).recordset[0];alreadyCheckedIn=!!prior?.CheckedInAt;if(!alreadyCheckedIn)await new sql.Request(tx).input('e',sql.UniqueIdentifier,d.eventId).input('u',sql.UniqueIdentifier,card.UserId).query(`MERGE EventAttendees t USING(SELECT @e EventId,@u UserId)s ON t.EventId=s.EventId AND t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET Status='GOING',CheckedInAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(EventId,UserId,Status,CheckedInAt) VALUES(@e,@u,'GOING',SYSUTCDATETIME());`)}if(d.meetingId){const session=(await new sql.Request(tx).input('m',sql.UniqueIdentifier,d.meetingId).input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT s.MeetingId FROM MeetingAttendanceSessions s WITH(UPDLOCK,HOLDLOCK) JOIN Meetings m WITH(UPDLOCK,HOLDLOCK) ON m.Id=s.MeetingId WHERE s.MeetingId=@m AND m.CommunityId=@c AND m.EndDateTime>SYSUTCDATETIME() AND s.IsActive=1 AND s.CodeExpiresAt>=SYSUTCDATETIME()`)).recordset[0];if(!session)throw new AppError(409,'Attendance is closed or expired');const prior=(await new sql.Request(tx).input('m',sql.UniqueIdentifier,d.meetingId).input('u',sql.UniqueIdentifier,card.UserId).query(`SELECT 1 Found FROM MeetingAttendance WITH(UPDLOCK,HOLDLOCK) WHERE MeetingId=@m AND UserId=@u`)).recordset[0];alreadyCheckedIn=!!prior;if(!prior)await new sql.Request(tx).input('m',sql.UniqueIdentifier,d.meetingId).input('u',sql.UniqueIdentifier,card.UserId).input('by',sql.UniqueIdentifier,req.user!.id).query(`INSERT INTO MeetingAttendance(MeetingId,UserId,Status,CheckInMethod,MarkedBy) VALUES(@m,@u,'PRESENT','CARD',@by)`)}await tx.commit();await audit(req.params.communityId,req.user!.id,'MEMBERSHIP_CARD_SCANNED','MembershipCard',card.CardId,{eventId:d.eventId,meetingId:d.meetingId,alreadyCheckedIn});res.json({success:true,alreadyCheckedIn,message:alreadyCheckedIn?'Already checked in.':'Check-in successful.',member:{userId:card.UserId,firstName:card.FirstName,lastName:card.LastName}})}catch(error){await tx.rollback();console.warn('Membership scan rejected',{communityId:req.params.communityId,scannerUserId:req.user!.id,eventId:d.eventId,meetingId:d.meetingId,error:String(error)});throw error}}));
